import{_ as g,c as t,o as e,aj as i}from"./chunks/framework.B-K7myP5.js";const c=JSON.parse('{"title":"Golang 常用命令","frontmatter":{"title":"Golang 常用命令","createTime":"2024/01/29 09:18:02","permalink":"/article/golang-help/","tags":["Golang"],"cover":"data:image/svg+xml;base64,","coverStyle":{"layout":"left","ratio":"1:1","width":56},"lastUpdated":"2026-01-22","link":"/posts/golang-help","layout":"doc","prev":{"text":"Golang 加密解密算法","link":"/posts/golang-encrypt"},"next":{"text":"Golang 格式化时间","link":"/posts/golang-time-format"}},"headers":[],"params":{"pkg":"golang-help"},"relativePath":"posts/golang-help.md","filePath":"posts/[pkg].md"}'),l={name:"posts/golang-help.md"};function I(n,o,M,d,s,N){return e(),t("div",null,[...o[0]||(o[0]=[i("<ul><li><strong><code>go build</code></strong> 编译包和依赖项，生成可执行文件。命令用于编译包和依赖项，生成可执行文件。当对Go程序进行修改后，需要使用go build命令重新编译程序，以生成新的可执行文件。该命令不会自动下载和安装依赖项，需要事先使用go get命令下载依赖项</li><li><strong><code>go run</code></strong> 编译并运行Go程序。该命令会临时编译程序并运行，不会生成可执行文件。在开发和测试阶段使用，用于快速运行程序并查看输出结果。</li><li><strong><code>go test</code></strong> 运行测试文件，会自动执行以Test为前缀的测试函数，并输出测试结果。该命令会自动编译测试文件和被测试的源文件，不需要手动编译。在测试阶段使用，用于自动化测试程序的正确性和性能。</li><li><strong><code>go get &lt;依赖路径&gt;</code></strong> 下载并安装指定的包和依赖项。它会自动下载所需的依赖项，并将它们安装到$GOPATH目录下。</li><li><strong><code>go mod download &lt;依赖路径&gt;</code></strong> 执行该命令之后，Go 会自动下载并安装依赖，安装后的依赖在 $GOPATH/pkg/mod 目录下。</li><li><strong><code>go install</code></strong> 编译包和依赖项，并将可执行文件安装到$GOPATH/bin目录下。在生产环境使用，用于部署程序。</li><li><strong><code>go clean</code></strong> 清理编译生成的文件和缓存文件。</li><li><strong><code>go mod init</code></strong> 初始化模块，创建go.mod文件。在开发和发布新模块时使用，用于管理模块依赖。</li><li><strong><code>go mod tidy</code></strong> 整理模块依赖，移除不需要的依赖。在开发和测试阶段使用，用于管理模块依赖。</li><li><strong><code>go clean -modcache</code></strong> 清理 Go 模块缓存</li><li><strong><code>go mod vendor</code></strong> 将依赖项复制到本地vendor目录下，方便离线构建。用于离线构建程序。</li><li><strong><code>go doc</code></strong> 查看Go文档，例如go doc fmt.Println可以查看fmt包中的Println函数的文档。在开发和学习阶段使用，用于查阅Go标准库和第三方库的文档。</li><li><strong><code>go vet</code></strong> 检查代码风格和潜在错误。在开发阶段使用，用于检查代码质量和发现潜在的错误。</li><li><strong><code>go fmt</code></strong> 格式化代码，使其符合Go语言的规范。用于统一代码风格和格式。</li><li><strong><code>go list -m all</code></strong> 显示依赖关系</li></ul>",1)])])}const r=g(l,[["render",I]]);export{c as __pageData,r as default};
